    for (const P of pieces) for (const q of P.flat) { const k = P.key + (q.X >= 0 ? '+' : '-'), a = (wmax[k] ??= new Float32Array(NB + 1)), x = cl01(q.t) * NB, i0 = Math.floor(x), i1 = Math.min(NB, i0 + 1); a[i0] = Math.max(a[i0], Math.abs(q.X)); a[i1] = Math.max(a[i1], Math.abs(q.X)) }
    for (const a of Object.values(wmax)) { let last = -1; for (let i = 0; i <= NB; i++) if (a[i] > 0) { if (last >= 0) for (let j = last + 1; j < i; j++) a[j] = a[last] + ((a[i] - a[last]) * (j - last)) / (i - last); last = i } }
