  // ---------------------------------------------------------------------------
  const M = {
    steel: mat({ color: COL.steel, metalness: 0.25, roughness: 0.45 }), plate: mat({ color: COL.plate, roughness: 0.5 }),
    bench: mat({ color: COL.bench, roughness: 0.8 }), floor: mat({ color: COL.floor, roughness: 1 }),
  }
  function barbell(scene) {
    const g = new T.Group()
    const bar = new T.Mesh(new T.CylinderGeometry(0.014, 0.014, 2.0, 12), M.steel)
    bar.rotation.z = Math.PI / 2
    g.add(bar)
    for (const x of [-0.82, 0.82]) {
      for (const [dx, r] of [[0, 0.225], [0.05 * Math.sign(x), 0.16]]) {
        const p = new T.Mesh(new T.CylinderGeometry(r, r, 0.045, 32), M.plate)
        p.rotation.z = Math.PI / 2; p.position.x = x + dx
        g.add(p)
      }
      const collar = new T.Mesh(new T.CylinderGeometry(0.03, 0.03, 0.05, 12), M.steel)
      collar.rotation.z = Math.PI / 2; collar.position.x = x - 0.06 * Math.sign(x)
      g.add(collar)
    }
    g.traverse((o) => { if (o.isMesh) o.castShadow = true })
    scene.add(g)
    return g
  }
  function floor(scene) {
    const plane = new T.Mesh(new T.PlaneGeometry(3.2, 3.2), M.floor)
    plane.rotation.x = -Math.PI / 2; plane.receiveShadow = true
    scene.add(plane)
    const grid = new T.GridHelper(3.2, 16, srgb(COL.grid), srgb(COL.grid))
    grid.position.y = 0.002
    scene.add(grid)
  }
  const KEYS = [{ t: 0, h: 0 }, { t: 0.45, h: 1 }, { t: 0.55, h: 1 }, { t: 0.95, h: 0 }, { t: 1, h: 0 }]
  function depth(cycle) {
    for (let i = 0; i < KEYS.length - 1; i++) if (cycle >= KEYS[i].t && cycle <= KEYS[i + 1].t) return lerp(KEYS[i].h, KEYS[i + 1].h, ease((cycle - KEYS[i].t) / (KEYS[i + 1].t - KEYS[i].t)))
    return 0
  }

  // --- Outils de décor partagés par les scènes -------------------------------------
  const frameAt = (P, u, f) => (X, Y, Z = 0) => {
    const s = u.clone().cross(f).normalize()
    return P.clone().add(s.multiplyScalar(X)).add(u.clone().multiplyScalar(Y)).add(f.clone().multiplyScalar(Z))
  }
  function mat2(scene, w, d, x = 0, z = 0) {
    const m = new T.Mesh(new T.BoxGeometry(w, 0.012, d), mat({ color: 0x3b4234, roughness: 0.9 }))
    m.position.set(x, 0.006, z); m.receiveShadow = true; scene.add(m)
  }
  function box2(scene, w, hgt, d, x, z) {
    const b = new T.Mesh(new T.BoxGeometry(w, hgt, d), M.bench); b.position.set(x, hgt / 2, z); b.castShadow = b.receiveShadow = true; scene.add(b)
  }

  // --- Registre des scènes : chaque fichier de scenes/ appelle scene(id, { build, cible, zoom, vues }) ---
  const REGISTRY = []
  function scene(id, def) { REGISTRY.push({ id, ...def }) }

