const grp = (parent, p = V(0, 0, 0), rot = [0, 0, 0]) => { const g = new T.Group(); g.position.copy(p); g.rotation.set(...rot); parent.add(g); return g }
const box = (g, w, h, d, m, x = 0, y = 0, z = 0) => add(g, new T.BoxGeometry(w, h, d), m, x, y, z)
// Boîte aux arêtes adoucies (carters, platines).
function rbox(g, w, h, d, m, x = 0, y = 0, z = 0, r = 0.012) {
  const s = new T.Shape(), hw = w / 2 - r, hh = h / 2 - r
  s.moveTo(-hw, -hh - r); s.lineTo(hw, -hh - r); s.quadraticCurveTo(hw + r, -hh - r, hw + r, -hh); s.lineTo(hw + r, hh)
  s.quadraticCurveTo(hw + r, hh + r, hw, hh + r); s.lineTo(-hw, hh + r); s.quadraticCurveTo(-hw - r, hh + r, -hw - r, hh)
  s.lineTo(-hw - r, -hh); s.quadraticCurveTo(-hw - r, -hh - r, -hw, -hh - r)
  const geo = new T.ExtrudeGeometry(s, { depth: d, bevelEnabled: false, curveSegments: 6 }); geo.translate(0, 0, -d / 2)
  return add(g, geo, m, x, y, z)
}
// Tube droit de a à b. prof : 'rond' | 'carre' | 'ovale' (ovale = tube Matrix, aplati selon `plat`).
function tube(g, a, b, r, m = M.frame, prof = 'rond', plat = null) {
  const d = b.clone().sub(a), L = d.length()
  let geo
  if (prof === 'carre') geo = new T.BoxGeometry(r * 2, L, r * 2)
  else geo = new T.CylinderGeometry(r, r, L, prof === 'ovale' ? 20 : 14)
  const o = add(g, geo, m)
  o.position.copy(a).add(b).multiplyScalar(0.5)
  o.quaternion.setFromUnitVectors(UP, d.normalize())
  if (prof === 'ovale') {
    // aplatit le tube dans la direction `plat` (par défaut : horizontale perpendiculaire au tube)
    const p = (plat ?? (Math.abs(d.y) > 0.9 ? V(0, 0, 1) : V(0, 1, 0).cross(d).normalize())).clone()
    const loc = p.applyQuaternion(o.quaternion.clone().invert())
    o.rotateY(Math.atan2(loc.z, loc.x)); o.scale.set(0.62, 1, 1)
  }
  return o
}
// Tube cintré passant par des points (châssis courbes façon Matrix).
function bent(g, pts, r, m = M.frame, tension = 0.2) {
  const curve = new T.CatmullRomCurve3(pts, false, 'catmullrom', tension)
  return add(g, new T.TubeGeometry(curve, Math.max(12, pts.length * 10), r, 14, false), m)
}
// Platine au sol sous un montant.
const foot = (g, x, z, w = 0.12, d = 0.12) => box(g, w, 0.02, d, M.base, x, 0.01, z)
// Coussin rembourré : w (largeur x), e (épaisseur y), d (longueur z), centré, posé à plat ; à faire pivoter via un groupe.
function pad(g, w, e, d, x = 0, y = 0, z = 0, m = M.pad) {
  const r = Math.min(w, d) * 0.2, s = new T.Shape(), hw = w / 2 - r, hd = d / 2 - r
  s.moveTo(-hw, -hd - r); s.lineTo(hw, -hd - r); s.quadraticCurveTo(hw + r, -hd - r, hw + r, -hd); s.lineTo(hw + r, hd)
  s.quadraticCurveTo(hw + r, hd + r, hw, hd + r); s.lineTo(-hw, hd + r); s.quadraticCurveTo(-hw - r, hd + r, -hw - r, hd)
  s.lineTo(-hw - r, -hd); s.quadraticCurveTo(-hw - r, -hd - r, -hw, -hd - r)
  const bev = Math.min(0.022, e * 0.42)
  const geo = new T.ExtrudeGeometry(s, { depth: Math.max(0.001, e - 2 * bev), bevelEnabled: true, bevelThickness: bev, bevelSize: bev * 0.9, bevelSegments: 4, curveSegments: 10 })
  geo.translate(0, 0, -(e - 2 * bev) / 2); geo.rotateX(-Math.PI / 2)
  const o = add(g, geo, m, x, y, z)
  // contreplaqué + coque sous la sellerie
  box(g, w * 0.94, 0.012, d * 0.94, M.dark, x, y - e / 2 - 0.006, z)
  return o
}
// Coussin vertical (dossier) : même chose basculé ; renvoie le groupe pour régler l'angle.
// Face rembourrée vers +z du groupe, hauteur selon y ; angle = bascule autour de x (> 0 : haut vers l'arrière... selon le signe voulu).
function backPad(g, w, e, h, p, angle = 0) {
  const k = grp(g, p, [angle, 0, 0]); pad(grp(k, V(0, 0, 0), [Math.PI / 2, 0, 0]), w, e, h)
  return k
}
// Boudin de mousse (rouleau) d'axe x.
function roller(g, c, len = 0.22, r = 0.05) {
  const o = add(g, new T.CylinderGeometry(r, r, len, 24), M.pad, c.x, c.y, c.z); o.rotation.z = Math.PI / 2
  for (const s of [-1, 1]) { const e = add(g, new T.CylinderGeometry(r * 0.55, r * 0.55, 0.012, 16), M.rubber, c.x + s * (len / 2 + 0.006), c.y, c.z); e.rotation.z = Math.PI / 2 }
  return o
}
// Poignée caoutchoutée de a à b.
function handle(g, a, b, r = 0.016) { tube(g, a, b, r * 0.7, M.chrome); const d = b.clone().sub(a); const m = a.clone().addScaledVector(d, 0.12), n = a.clone().addScaledVector(d, 0.88); return tube(g, m, n, r, M.rubber) }
// Molette / goupille de réglage kaki.
const knob = (g, p, r = 0.018) => add(g, new T.SphereGeometry(r, 14, 10), M.accent, p.x, p.y, p.z)
// Plateau de pieds antidérapant (normale = +z local).
function footplate(g, w, h, p, rot = [0, 0, 0]) {
  const k = grp(g, p, rot); rbox(k, w, h, 0.03, M.dark, 0, 0, 0, 0.03)
  for (let i = -3; i <= 3; i++) box(k, w * 0.86, 0.006, 0.004, M.rubber, 0, i * h * 0.12, 0.017)
  return k
}
// Disque de fonte (axe local y), avec trou et lèvre.
function disc(g, r, w, p = V(0, 0, 0), m = M.iron) {
  const k = grp(g, p)
  const s = new T.Shape(); s.absarc(0, 0, r, 0, Math.PI * 2, false); const h = new T.Path(); h.absarc(0, 0, 0.026, 0, Math.PI * 2, true); s.holes.push(h)
  const geo = new T.ExtrudeGeometry(s, { depth: w, bevelEnabled: true, bevelThickness: 0.004, bevelSize: 0.004, bevelSegments: 2, curveSegments: 32 })
  geo.translate(0, 0, -w / 2); geo.rotateX(Math.PI / 2)
  add(k, geo, m)
  // Même dessin sur les deux faces (comme le « disque seul ») : lèvre, moyeu et rebord extérieur.
  for (const s of [-1, 1]) {
    const lip = add(k, new T.TorusGeometry(r * 0.72, 0.006, 6, 32), m); lip.rotation.x = Math.PI / 2; lip.position.y = s * w / 2
    const hub = add(k, new T.TorusGeometry(0.042, 0.007, 6, 24), m); hub.rotation.x = Math.PI / 2; hub.position.y = s * w / 2
    const rim = add(k, new T.TorusGeometry(r - 0.008, 0.005, 6, 40), m); rim.rotation.x = Math.PI / 2; rim.position.y = s * (w / 2 + 0.001)
  }
  return k
}
// Corne porte-disques (manchon) de a vers dir, avec n disques de 20 kg (r 0.225) chargés depuis la base.
function horn(g, a, dir, n = 0, len = 0.3, r = 0.225) {
  const d = dir.clone().normalize(), b = a.clone().addScaledVector(d, len)
  tube(g, a, b, 0.025, M.chrome)
  const col = tube(g, a, a.clone().addScaledVector(d, 0.02), 0.04, M.frame) // butée
  add(g, new T.CylinderGeometry(0.03, 0.03, 0.01, 16), M.chrome).position.copy(b)
  for (let i = 0; i < n; i++) { const k = disc(g, r, 0.045, a.clone().addScaledVector(d, 0.045 + i * 0.05)); k.quaternion.setFromUnitVectors(UP, d) }
  return col
}
// Poulie (réa dans sa chape). axis : axe de rotation du réa.
function pulley(g, p, axis = V(0, 0, 1), r = 0.05) {
  const k = grp(g, p); k.quaternion.setFromUnitVectors(UP, axis.clone().normalize())
  add(k, new T.CylinderGeometry(r, r, 0.024, 24), M.dark)
  add(k, new T.CylinderGeometry(r * 0.35, r * 0.35, 0.03, 12), M.chrome)
  for (const s of [-1, 1]) { const c = add(k, new T.BoxGeometry(r * 2.4, 0.006, r * 2.4), M.frame, 0, s * 0.018, 0); c.castShadow = false }
  return k
}
// Câble ou sangle à points variables : const c = cableDyn(g); c.set([p0, p1, ...]) à chaque image.
function cableDyn(g, r = 0.0035, m = M.cable, n = 8) {
  const segs = []
  for (let i = 0; i < n; i++) { const o = add(g, new T.CylinderGeometry(r, r, 1, 6), m); o.visible = false; segs.push(o) }
  return {
    set(pts) {
      segs.forEach((o, i) => {
        if (i >= pts.length - 1) { o.visible = false; return }
        const a = pts[i], b = pts[i + 1], d = b.clone().sub(a), L = d.length()
        o.visible = L > 1e-4; if (!o.visible) return
        o.position.copy(a).add(b).multiplyScalar(0.5); o.scale.set(1, L, 1); o.quaternion.setFromUnitVectors(UP, d.normalize())
      })
    },
  }
}
// Pile de charges carénée façon Matrix Ultra (hauteur de carénage 1,35 m, vitres avant et arrière).
// Renvoie { lift(m) : soulève la plaque de tête et les plaques choisies, top() : point d'attache du câble (repère g) }.
function tour(g, p, o = {}) {
  const { w = 0.36, d = 0.2, h = 1.35, n = 18, pin = 6, ry = 0, coque = true, fente = false } = o
  const k = grp(g, p, [0, ry, 0])
  const ph = 0.03, gap = 0.004, y0 = 0.1
  // socle et châssis de la tour
  rbox(k, w + 0.16, 0.05, d + 0.14, M.base, 0, 0.025, 0, 0.02)
  for (const s of [-1, 1]) rbox(k, 0.07, h, 0.1, M.frame, s * (w / 2 + 0.05), h / 2, 0, 0.02)
  if (fente) for (const s of [-1, 1]) rbox(k, (w + 0.17) / 2 - 0.02, 0.08, d + 0.08, M.frame, s * ((w + 0.17) / 4 + 0.02), h + 0.04, 0, 0.03) // chapeau fendu : le câble sort par le milieu
  else rbox(k, w + 0.17, 0.08, d + 0.08, M.frame, 0, h + 0.04, 0, 0.03)
  // tiges de guidage
  for (const s of [-1, 1]) tube(k, V(s * w * 0.36, 0.05, 0), V(s * w * 0.36, h, 0), 0.0095, M.chrome)
  // plaques
  const mob = grp(k), fix = grp(k)
  for (let i = 0; i < n; i++) {
    const y = y0 + i * (ph + gap) + ph / 2, tgt = i >= n - pin ? mob : fix
    rbox(tgt, w, ph, d * 0.62, M.iron, 0, y, 0, 0.006)
    box(tgt, 0.05, 0.016, 0.002, M.accent, w * 0.3, y, d * 0.31 + 0.001).castShadow = false // étiquette de poids
  }
  const ty = y0 + n * (ph + gap) + 0.02
  rbox(mob, w * 0.92, 0.04, d * 0.66, M.dark, 0, ty, 0, 0.01) // plaque de tête
  tube(mob, V(0, y0 + (n - pin) * (ph + gap), 0), V(0, ty + 0.03, 0), 0.008, M.chrome) // tige de sélection
  const py = y0 + (n - pin) * (ph + gap) + ph / 2
  tube(mob, V(0, py, d * 0.31 + 0.05), V(0, py, 0), 0.006, M.chrome); knob(mob, V(0, py, d * 0.31 + 0.06), 0.016) // goupille
  if (coque) {
    for (const s of [-1, 1]) { const v = box(k, w + 0.04, h - 0.18, 0.006, M.glass, 0, h / 2 + 0.02, s * (d / 2 + 0.035)); v.castShadow = false }
    for (const s of [-1, 1]) for (const y of [0.11, h - 0.05]) box(k, w + 0.06, 0.03, 0.02, M.frame, 0, y, s * (d / 2 + 0.035))
  }
  const top = V(0, ty + 0.03, 0)
  return {
    group: k,
    lift(m) { mob.position.y = clamp(m, 0, h - ty - 0.06) },
    top() { g.updateMatrixWorld(true); return g.worldToLocal(k.localToWorld(top.clone().add(V(0, mob.position.y, 0)))) }, // dans le repère de g, même si g est tourné ou déplacé
    head: V(0, h + 0.08, 0), // sommet du carénage (repère de la tour)
  }
}
// Point d'un groupe enfant ramené dans le repère du groupe g (à appeler après avoir posé les rotations).
function inG(g, child, p) { g.updateMatrixWorld(true); return g.worldToLocal(child.localToWorld(p.clone())) }
// Petit pied stabilisateur en caoutchouc.
const sabot = (g, x, z) => add(g, new T.CylinderGeometry(0.035, 0.04, 0.02, 12), M.rubber, x, 0.01, z)
// Assise standard d’une machine à pile : longeron, poteau, siège (sy, sz, inclinaison sa), dossier (centre bp, angle ba, hauteur bh).
function assise(g, o = {}) {
  const { sy = 0.5, sz = 0, sa = -0.08, bp = V(0, 0.9, -0.3), ba = -0.15, bh = 0.6, z0 = -0.7, z1 = 0.4, dossier = true } = o
  tube(g, V(0, 0.04, z0), V(0, 0.04, z1), 0.045, M.frame, 'ovale', V(0, 1, 0)); foot(g, 0, z0, 0.5, 0.1); foot(g, 0, z1, 0.5, 0.1)
  tube(g, V(0, 0.04, sz - 0.02), V(0, sy - 0.07, sz - 0.02), 0.045, M.frame, 'ovale')
  const seat = grp(g, V(0, sy, sz), [sa, 0, 0]); pad(seat, 0.44, 0.08, 0.42); knob(g, V(0.07, sy - 0.14, sz))
  if (dossier) {
    const top = bp.clone().add(V(0, Math.cos(ba) * bh / 2, Math.sin(ba) * bh / 2 - 0.08))
    bent(g, [V(0, 0.04, bp.z - 0.25), V(0, bp.y * 0.5, bp.z - 0.14), top], 0.04)
    backPad(g, 0.42, 0.08, bh, bp, ba)
  }
  return seat
}
// Bras mobile entraînant la pile par un câble : renvoie { g: groupe pivot } ; câble mis à jour par cable(t-points).
function axe(g, p, dir = 'x', len = 0.16) {
  const o = add(g, new T.CylinderGeometry(0.03, 0.03, len, 16), M.chrome, p.x, p.y, p.z)
  if (dir === 'x') o.rotation.z = Math.PI / 2; else if (dir === 'z') o.rotation.x = Math.PI / 2
  return o
}
// Barre olympique (2,20 m, axe x, origine au centre) avec disques de rayon r par côté : nb = [[r, épaisseur], ...].
function barreOly(g, p = V(0, 0, 0), nb = [[0.225, 0.045]], len = 2.2, grip = 0.0145) {
  const k = grp(g, p)
  tube(k, V(-0.655, 0, 0), V(0.655, 0, 0), grip, M.grip)
  for (const s of [-1, 1]) {
    tube(k, V(s * 0.655, 0, 0), V(s * 0.68, 0, 0), 0.03, M.chrome) // bague
    tube(k, V(s * 0.68, 0, 0), V(s * len / 2, 0, 0), 0.025, M.chrome) // manchon
    let x = 0.7
    for (const [r, w] of nb) { disc(k, r, w, V(s * (x + w / 2), 0, 0)).rotation.z = Math.PI / 2; x += w + 0.004 }
    if (nb.length) { const c = add(k, new T.CylinderGeometry(0.04, 0.04, 0.03, 16), M.accent, s * (x + 0.015), 0, 0); c.rotation.z = Math.PI / 2 } // collier de serrage
  }
  return k
}
// Haltère hexagonal (axe x, origine au milieu de la poignée).
function hexa(g, p = V(0, 0, 0), r = 0.075, w = 0.1) {
  const k = grp(g, p)
  tube(k, V(-0.07, 0, 0), V(0.07, 0, 0), 0.0165, M.grip)
  for (const s of [-1, 1]) {
    const h = add(k, new T.CylinderGeometry(r, r, w, 6), M.rubber, s * (0.07 + w / 2), 0, 0); h.rotation.z = Math.PI / 2
    const c = add(k, new T.CylinderGeometry(0.03, 0.03, 0.004, 20), M.chrome, s * (0.07 + w + 0.002), 0, 0); c.rotation.z = Math.PI / 2
  }
  return k
}
// Banc plat commercial : pieds en T avant/arrière, coussin 1,20 m × 0,30, hauteur 0,44.
function bancPlat(g, p = V(0, 0, 0), L = 1.2, H = 0.44) {
  const k = grp(g, p)
  for (const z of [-L / 2 + 0.1, L / 2 - 0.1]) { tube(k, V(-0.24, 0.03, z), V(0.24, 0.03, z), 0.035, M.frame, 'ovale', V(0, 1, 0)); tube(k, V(0, 0.03, z), V(0, H - 0.07, z * 0.8), 0.035, M.frame, 'ovale'); sabot(k, -0.22, z); sabot(k, 0.22, z) }
  tube(k, V(0, H - 0.07, -L / 2 + 0.15), V(0, H - 0.07, L / 2 - 0.15), 0.03, M.frame, 'carre')
  pad(grp(k, V(0, H - 0.02, 0)), 0.3, 0.09, L)
  return k
}
// Colonne de poulie réglable (type Matrix Aura / Versa) : rail vertical, chariot à poulie orientable.
// Renvoie { pulley(): point de sortie du câble (repère g), setH(h) }.
function colonnePoulie(g, p, o = {}) {
  const { ry = 0, h = 1.0, n = 20, hmax = 2.0 } = o
  const k = grp(g, p, [0, ry, 0])
  const tw = tour(k, V(0, 0, -0.12), { n, pin: 6, h: 1.35, fente: true })
  rbox(k, 0.12, hmax + 0.15, 0.1, M.frame, 0, (hmax + 0.15) / 2, 0.08, 0.02) // rail
  rbox(k, 0.14, 0.05, 0.3, M.base, 0, 0.025, 0.0, 0.02); rbox(k, 0.12, 0.08, 0.06, M.frame, 0, 1.39, 0.02, 0.02) // liaisons tour ↔ rail
  // Renvois visibles : P1 sur le chapeau de la tour, au-dessus de la pile ; P2 en tête du rail.
  const P1 = V(0, 1.5, -0.07), P2 = V(0, hmax + 0.21, 0.1)
  pulley(k, P1, V(1, 0, 0), 0.05); pulley(k, P2, V(1, 0, 0), 0.05)
  for (const s of [-1, 1]) { box(k, 0.008, 0.12, 0.06, M.frame, s * 0.022, 1.46, -0.07); box(k, 0.008, 0.12, 0.08, M.frame, s * 0.022, hmax + 0.17, 0.1) } // flasques
  for (let y = 0.25; y < hmax; y += 0.1) box(k, 0.02, 0.012, 0.004, M.accent, 0.045, y, 0.132).castShadow = false
  const car = grp(k, V(0, h, 0.16)); rbox(car, 0.16, 0.18, 0.08, M.dark, 0, 0, 0, 0.02); knob(car, V(0.09, 0.04, 0), 0.016)
  const sw = grp(car, V(0, -0.02, 0.07)); pulley(sw, V(0, 0, 0.03), V(1, 0, 0), 0.04)
  const cab = cableDyn(g, 0.0035, M.cable, 10)
  return {
    group: k, tw,
    setH(y) { car.position.y = y },
    pulley() { return inG(g, sw, V(0, 0, 0.03)) },
    run(handleP, pulled) {
      // Câble : haut de la pile → P1 → P2 → descend devant le rail jusqu’au chariot → réa pivotant → anneau de la poignée.
      tw.lift(clamp(pulled * 0.5, 0, 0.5))
      // la chape pivote autour de la verticale pour que le câble reste dans le plan du réa
      g.updateMatrixWorld(true); const hk = k.worldToLocal(g.localToWorld(handleP.clone())).sub(V(0, car.position.y - 0.02, 0.23))
      sw.rotation.y = Math.abs(hk.x) + Math.abs(hk.z) > 1e-3 ? clamp(Math.atan2(hk.x, Math.max(hk.z, 0.02)), -1.4, 1.4) : 0
      const y = car.position.y
      const L = (v) => inG(g, k, v)
      cab.set([L(tw.top()), L(V(0, P1.y, -0.12)), L(V(0, P1.y + 0.05, -0.07)), L(V(0, P2.y + 0.05, 0.1)), L(V(0, P2.y, 0.15)), L(V(0, y + 0.09, 0.15)), L(V(0, y - 0.02, 0.22)), (() => { const c = this.pulley(); return c.add(handleP.clone().sub(c).setLength(0.04)) })(), handleP])
    },
  }
}
// Poignée simple en D (étrier arrondi) au point p, orientée par l’axe de prise d ; la poignée tourne dans l’étrier.
function poigneeD(g, p, d = V(1, 0, 0)) {
  const k = grp(g, p); k.quaternion.setFromUnitVectors(V(1, 0, 0), d.clone().normalize())
  const c = new T.CatmullRomCurve3([V(-0.062, 0, 0), V(-0.058, 0.045, 0), V(-0.03, 0.085, 0), V(0, 0.1, 0), V(0.03, 0.085, 0), V(0.058, 0.045, 0), V(0.062, 0, 0)], false, 'centripetal')
  add(k, new T.TubeGeometry(c, 48, 0.0075, 12, false), M.chrome)
  add(k, new T.TorusGeometry(0.014, 0.004, 10, 20), M.chrome, 0, 0.112, 0) // anneau d’accroche
  tube(k, V(-0.064, 0, 0), V(0.064, 0, 0), 0.008, M.chrome)
  const gr = add(k, new T.CylinderGeometry(0.017, 0.017, 0.1, 24), M.rubber); gr.rotation.z = Math.PI / 2
  for (const s of [-1, 1]) { const b = add(k, new T.TorusGeometry(0.016, 0.003, 8, 24), M.rubber, s * 0.05, 0, 0); b.rotation.y = Math.PI / 2 }
  return k
}
// Accroche une poignée en D par son anneau au point p, l’étrier tourné vers `vers` (la poulie) : le câble finit dans l’anneau.
function accrocher(h, p, vers) { const d = vers.clone().sub(p).normalize(); h.quaternion.setFromUnitVectors(UP, d); h.position.copy(p).addScaledVector(d, -0.112) }
