    tube(g, V(s * 0.65, 0.04, 0.45), V(s * 0.65, 0.7, 0.04), 0.025, M.frame, 'carre'); tube(g, V(s * 0.65, 0.04, -0.45), V(s * 0.65, 0.7, -0.04), 0.025, M.frame, 'carre') // jambes de force
