/*@ {"id": "batons_nordique", "nom": "Bâtons de marche nordique", "famille": "Cardio", "ref": "paire de bâtons carbone à gantelet et embout caoutchouc", "dims": [0.2, 0.1, 1.2], "liste": "Bâtons de marche nordique", "note": "Gantelets attachés au poignet, embouts inclinés vers l’arrière."} */
