  for (const z of [-1.0, 0.6]) tube(g, V(-0.45, 0.05, z), V(0.45, 0.05, z), 0.045, M.frame, 'carre')
  tube(g, V(0, 0.05, 0.25), V(0, 0.37, 0.2), 0.05, M.frame, 'carre'); tube(g, V(0, 0.05, -0.6), V(0, 0.6, -0.5), 0.05, M.frame, 'carre')
  const seat = grp(g, V(0, 0.43, 0.22), [-0.05, 0, 0]); pad(seat, 0.44, 0.08, 0.38) // avant abaissé de ~5 cm (cuisses)
  backPad(g, 0.44, 0.09, 0.85, V(0, 0.724, -0.311), -0.95) // reculé de 0,19 perpendiculairement : bassin ~0,15 devant le plan du dossier ; bas du coussin à l’arrière du siège
  // Mannequin testé sur le dossier : épaules à (±0,20 ; 0,91 ; -0,31). Prises de (±0,24 ; 1,03 ; -0,22) au départ
