  for (const s of [-1, 1]) { tube(g, V(s * 0.4, 0.05, -0.9), V(s * 0.4, P.y, P.z - 0.04), 0.05, M.frame, 'carre'); tube(g, V(s * 0.4, 0.05, -0.35), V(s * 0.4, 1.0, -0.82), 0.035, M.frame, 'carre'); axe(g, V(s * 0.4, P.y, P.z), 'x', 0.12) }
  tube(g, V(-0.4, P.y, P.z - 0.08), V(0.4, P.y, P.z - 0.08), 0.04, M.frame, 'carre')
  const H = -0.595, Z = 0.56
