    handle(a, V(-s * 0.04, H, Z), V(-s * 0.28, H, Z), 0.018) // prise horizontale, parallèle au sol
    // bout arrondi côté intérieur qui repart en diagonale vers l’extérieur (prise inclinée)
    bent(a, [V(-s * 0.27, H, Z), V(-s * 0.32, H, Z + 0.02), V(-s * 0.33, H - 0.02, Z + 0.07), V(-s * 0.27, H - 0.06, Z + 0.13), V(-s * 0.19, H - 0.1, Z + 0.18)], 0.012, M.chrome)
    tube(a, V(-s * 0.31, H - 0.03, Z + 0.09), V(-s * 0.2, H - 0.095, Z + 0.175), 0.018, M.rubber)
