  handle(arm, V(-0.3, 0.232, -0.036), V(-0.08, 0.232, -0.036), 0.018); handle(arm, V(0.08, 0.232, -0.036), V(0.3, 0.232, -0.036), 0.018)
  tube(arm, V(-0.08, 0.232, -0.036), V(0.08, 0.232, -0.036), 0.012, M.chrome)
  const cab = cableDyn(g)
  return { set(t) { arm.rotation.x = 1.5 * t; tw.lift(0.15 * t); cab.set([V(0.3, PV.y, PV.z), V(0, 1.38, 0.5), tw.top()]) } }
