  knob(g, V(0.06, 0.45, PZ - 0.12))
  // Bloc pieds : poteau avant, flasques, plateau vertical, boudins.
  const FZ = 0.5
  tube(g, V(0, 0.06, FZ + 0.12), V(0, 0.82, FZ + 0.06), 0.045, M.frame, 'carre')
  for (const s of [-1, 1]) box(g, 0.012, 0.36, 0.08, M.frame, s * 0.21, 0.98, FZ + 0.08)
  box(g, 0.44, 0.03, 0.22, M.frame, 0, 0.8, FZ + 0.02)
  footplate(g, 0.4, 0.34, V(0, 1.02, FZ + 0.12), [0, Math.PI, 0]) // plante des pieds contre le plateau
  for (const [y, z] of [[0.9, FZ - 0.04], [1.12, FZ + 0.02]]) { tube(g, V(-0.21, y, z), V(0.21, y, z), 0.012, M.chrome); for (const s of [-1, 1]) roller(g, V(s * 0.1, y, z), 0.15, 0.045) }
