  tube(g, V(0, 0.05, -0.15), V(0, 0.3, -0.15), 0.05, M.frame, 'carre'); tube(g, V(0, 0.05, -0.62), V(0, 0.5, -0.62), 0.05, M.frame, 'carre')
  const seat = grp(g, V(0, 0.36, -0.12), [0.25, 0, 0]); pad(seat, 0.46, 0.09, 0.42)
