      for (const c of it.g.children) if (road ? near(c, 0, 0.92, -0.18) : near(c, 0, 0.98, -0.37) || near(c, 0, 0.775, -0.3)) c.position.add(V(0, -DY, DZ))
      if (road) Object.assign(B, { S: V(0, 0.945 + SADDLE - 0.075, -0.18 + DZ), C: V(0, 0.33, 0), G: V(0, 0.885, 0.475), gx: 0.18, px: 0.1 })
      else Object.assign(B, { S: V(0, 1.015 - DY + SADDLE - 0.075, -0.37 + DZ), C: V(0, 0.35, 0), G: V(0, 1.125, 0.32), gx: 0.2, px: 0.19 })
      B.lib = true
